// === Tab: mySketch ===
foliage=['#fe96d2','#c2854f','#aab193','#828757','#baaf51','#555713','#999c27', '#303d13','#9b6560','#91a54b','#4d662d']
pads=['#f2a955','#d6e445','#b0cb2d','#777b42','#9daf42','#7d9f25','#f5d53b','#bdbc9b','#a0a771','#ab473c']
let simplex

function setup() {
	createCanvas(windowWidth, windowHeight);
	blendMode(HARD_LIGHT)
	simplex= new OpenSimplexNoise(Date.now())
	let sky= color('#C1EAFF')
	sky.setAlpha(255)
	fill(sky)
	noStroke()
	rect(0, height/3-height/200, width, height*0.666)
	for(let x=0; x<width+5; x+=1){
	 strokeWeight(1)
   strokeCap(SQUARE)

		let shading = map(noise(x/50), 0, 1, 0, foliage.length)
				let c1 = color(foliage[floor(shading)])
				let c2 = color(foliage[floor((shading + 1) % foliage.length)])
				let mix = fract(shading)
				let coloring = lerpColor(c1, c2, mix)
	 stroke(coloring)
	line(x, 0, x, height/3-height/200)
	sky.setAlpha(255)
	stroke(sky)
	let l=map(noise(x/100), 0, 1, 0, height/3)
	let cs= drawingContext.createLinearGradient(x, 0, x, l)
	  cs.addColorStop(0.3, sky)
		cs.addColorStop(1, coloring)
		drawingContext.fillStyle= cs

		noStroke()
	rectMode(CENTER)
	rect(x, l/2, 2, l-1)



	}
	blendMode(HARD_LIGHT)


	noFill()
	for(let x=-20; x<width+20; x+=1){
		var shading = map(noise(x/50), 0, 1, 0, foliage.length)
				var c1 = color(foliage[floor(shading)])
				var c2 = color(foliage[floor((shading + 1) % foliage.length)])
				var mix = fract(shading)
				var coloring = lerpColor(c1, c2, mix)
				coloring.setAlpha(200)
	 stroke(coloring)
		beginShape()
		strokeWeight(1)
		for(let y= height/3-height/200; y<height+20; y+=5){
			let xoff= map(simplex.noise2D(x/100, y/30), -1, 1, -20, 20)
			vertex(x+xoff, y)
		}
		endShape()
	}
	blendMode(BLEND)
	let yBase= height/100
	let xBase= yBase*2
	for(let y=height/3; y<height+yBase; y+=yBase){
		for(let x=0; x<width+xBase; x+=xBase){
  yBase= map(y, height/3, height, height/100, height/5)
	xBase= yBase*2
	var xoff= map(simplex.noise2D(x/20, y/20), -1, 1, -xBase/4, xBase/4)
	let yoff= map(simplex.noise2D(x, y/50), -1, 1, 0, yBase/2)		

	let placement= simplex.noise2D(x/50, y/50)
	if(placement>0){
		strokeWeight(xBase/50)
		stroke(0, 40)
		noStroke()
		fill(255)

		let pc1= color(random(pads))
		let pc2= color(random(pads))
		let pc3= color(random(pads))

		pColor= drawingContext.createRadialGradient(x+xoff, y+yoff, xBase*1.25, x+random(-xBase/10, xBase/10), y-yBase/6, 1)
	  pColor.addColorStop(0, pc1)
		 pColor.addColorStop(0.4, pc2)
		pColor.addColorStop(1, pc3)
		drawingContext.fillStyle= pColor




		beginShape()
		for(let i=0; i<=TAU; i+=TAU/50){
			let xPoff= map(simplex.noise2D(x, sin(i)), -1, 1, xBase/12, -xBase/12)
			let yPoff= map(simplex.noise2D(y, cos(i)), -1, 1, yBase/12, -yBase/12)
			curveVertex(x+sin(i)*xBase*0.45+xPoff, y+cos(i)*yBase*0.45+yPoff)

		}
		endShape()


	for(let i=0; i<=TAU; i+=TAU/100){
			var xPoff= map(simplex.noise2D(x, sin(i/10)), -1, 1, xBase/6, -xBase/6)
			var yPoff= map(simplex.noise2D(y, cos(i/10)), -1, 1, yBase/6, -yBase/6)
			let r= random(0.45)
			let s= random(yBase/50, yBase/4)
			let d= map(noise(r/10, i), 0, 1, r*10, 255)
			push()
			fill(d, 5)
		  strokeWeight(s/10)
			noStroke()
			ellipse(x+sin(i)*xBase*r+xPoff, y+cos(i)*yBase*r+yPoff, s*2, s)
		stroke(d, 3)
		line(x, y, x+sin(i)*xBase*r+xPoff, y+cos(i)*yBase*r+yPoff)
			pop()
		}	
		}

	if(placement<-0.5){
	lily(x, y, yBase*0.75)	

	}

	}

	}	


}


function lily(x, y, s){
	let lC1='#ee9e82'
	let lC2='#FBEED9'
	let mid='#fdbb6b'
	strokeWeight(s/200)
	stroke(0, 20)
	for(let r=0.1; r<=1; r+=0.1){
	fill(0, 10)
	ellipse(x, y, s*1.3*r, s/1.5*r)
	}


	fill(255)



 //noStroke()
	push()
	translate(x, y)

	for(let i=-PI/2.5; i<=PI/2.5; i+=PI/8){

		let coff= map(noise(x, y, i+1), 0, 1, -s/3, s/3)
		lColor= drawingContext.createRadialGradient(coff, coff+s/10, s, 0, s/10, 1)
	  lColor.addColorStop(0, lC2)
		 lColor.addColorStop(1, lC1)
		drawingContext.fillStyle= lColor
	push()
	rotate(i)
	bezier(0, -s, -s/2 ,0 , s/2,0 ,0, -s)
	pop()
	}

	let midC1= mid
	let midC2= color(255, 0)
	midColor= drawingContext.createRadialGradient(0, -s/10, s, 0, -s/10, 1)
	  midColor.addColorStop(0, midC2)
		 midColor.addColorStop(0.66, midC1)
		drawingContext.fillStyle= midColor
	for(let i=-PI/4; i<=PI/4; i+=PI/10){
		push()
		rotate(i)
		bezier(0, -s*0.77, -s/3 ,0 , s/3,0 ,0, -s*0.75)
		pop()
	}


	for(let i=-PI/2.8; i<=0; i+=PI/8){

		var coff= map(noise(x, y, i), 0, 1, -s/3, s/3)
		lColor= drawingContext.createRadialGradient(coff, coff, s*0.75, 0, s*0.25, 1)
	  lColor.addColorStop(0, lC2)
		 lColor.addColorStop(1, lC1)
		drawingContext.fillStyle= lColor
		push()
		rotate(i)
		let off=map(i, -PI/2, 0, 4, 3)
		bezier(0, -s+s/off, -s/2 ,s/off , s/2,s/off ,0, -s+s/off)
		pop()
		push()
		rotate(-i)
		bezier(0, -s+s/off, -s/2 ,s/off , s/2,s/off ,0, -s+s/off)
		pop()
	}
	pop()


}

